from typing import List, Dict, Any, Literal, Optional
from dataclasses import dataclass

@dataclass
class TranscriptionConfig:
    region: str
    api_key: str
    job_name: Optional[str] = None

@dataclass
class TranscriptionPayload:
    audio_uri: str
    language_code: str
    diarization_enabled: bool = False
    word_level_timestamps_enabled: bool = False

@dataclass
class TranscriptionJob:
    job_id: str
    status: Literal['NOT_STARTED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'SUBMITTED']
    results: Optional[Dict[str, Any]] = None

@dataclass
class TranscriptSegment:
    start_time: str
    end_time: str
    text: str
    speaker: Optional[int] = None
    words: Optional[List[Dict[str, Any]]] = None

@dataclass
class DiarizationResult:
    segments: List[TranscriptSegment]

@dataclass
class TimestampResult:
    segments: List[TranscriptSegment]

import os
import requests
from speech_models import TranscriptionConfig

class AzureSpeechClient:
    def __init__(self, config: TranscriptionConfig):
        self.region = config.region
        self.api_key = config.api_key
        self.base_url = f"https://{self.region}.api.cognitive.microsoft.com/speechtotext/v3.1"

    def _headers(self):
        return {'Ocp-Apim-Subscription-Key': self.api_key}

    def get_transcription_status(self, job_id: str):
        url = f"{self.base_url}/transcriptions/{job_id}"
        response = requests.get(url, headers=self._headers(), timeout=30)
        response.raise_for_status()
        return response.json()

    def get_transcription_result(self, job_id: str, result_url: str):
        headers = self._headers()
        headers['Accept'] = 'application/json'
        response = requests.get(result_url, headers=headers, timeout=30)
        response.raise_for_status()
        return response.json()

